rules.logic:
// Avoid duplicating the injected card
if (document.getElementById('community-shortcut-card')) return;

const originalOption = document.querySelector('.need-more-help-option');
if (!originalOption) return;

// Clone the anchor link
const clone = originalOption.cloneNode(true);
clone.style.cssText = '';

// Build the card wrapper
const card = document.createElement('div');
card.id = 'community-shortcut-card';
card.style.cssText = [
  'display: flex',
  'align-items: center',
  'gap: 12px',
  'margin-top: 14px',
  'margin-bottom: 4px',
  'padding: 12px 16px',
  'background: #e8f0fe',
  'border: 1.5px solid #4285f4',
  'border-radius: 12px',
  'max-width: 600px',
].join(';');

// Label
const label = document.createElement('span');
label.style.cssText = 'font-size: 12px; font-weight: 600; color: #4285f4; text-transform: uppercase; letter-spacing: 0.5px; white-space: nowrap;';
label.textContent = 'Skip the article →';

// Style the cloned link
clone.style.cssText = [
  'display: flex',
  'align-items: center',
  'gap: 10px',
  'text-decoration: none',
  'color: inherit',
  'flex: 1',
].join(';');

// Style title and snippet inside clone
const title = clone.querySelector('.need-more-help-option__title');
const snippet = clone.querySelector('.need-more-help-option__snippet');
if (title) { title.style.cssText = 'font-weight: 700; font-size: 14px; color: #1a73e8; display: block;'; }
if (snippet) { snippet.style.cssText = 'font-size: 12px; color: #555; display: block;'; }

card.appendChild(label);
card.appendChild(clone);

element.insertAdjacentElement('afterend', card);
